"use strict";
// A strict CommonJS script: `this` is never the global object by a plain
// call, so a key no literal names reads nothing of it; a static key that
// names no global reads nothing either.
var store = {
  values: { a: 1 },
  get: function (key) {
    return this.values[key];
  },
};
function Counter() {
  this.name = "counter";
}
new Counter();
store.get("a");
module.exports = { store: store };
